matcher.js.source:
// Activity matcher: scores how similar two free-text "what are you doing" prompts are.
//
// Score (0..1) blends three signals:
//   1. Category overlap — words are mapped to broad activity categories
//      ("lifting", "gym", "workout" -> fitness) so different phrasings still match.
//   2. Keyword overlap — cosine similarity over stemmed, stopword-free tokens.
//   3. Fuzzy overlap — character trigram similarity, which tolerates typos
//      ("progamming" vs "programming").

const STOPWORDS = new Set(
  `a an the and or but if so to of in on at for with from by about into over after before
  i im i'm me my mine we us our you your he she it they them their this that these those
  am is are was were be been being do does did doing done have has had having
  just now right currently rn atm some any all very really kinda sort of like want wanna gonna
  going go get getting got trying try tryna little bit lot new up out off here there
  someone somebody anyone anybody people person together with who what how when where why
  can could would should will shall may might must need looking look for`
    .split(/\s+/)
    .filter(Boolean)
);

// Category -> trigger stems. Words are matched after stemming, and prefixes of 4+ chars count.
const CATEGORIES = {
  coding: ['code', 'coding', 'program', 'develop', 'dev', 'debug', 'hack', 'hackathon', 'javascript', 'python', 'java', 'react', 'software', 'app', 'website', 'leetcode', 'algorithm', 'typescript', 'rust', 'golang', 'api', 'frontend', 'backend', 'engineer'],
  studying: ['study', 'studi', 'homework', 'exam', 'test', 'learn', 'revis', 'lectur', 'class', 'course', 'assignment', 'essay', 'thesis', 'research', 'math', 'calculus', 'physic', 'chemistr', 'biolog', 'history', 'school', 'university', 'college', 'quiz', 'flashcard', 'pomodoro'],
  reading: ['read', 'book', 'novel', 'kindle', 'librar', 'poem', 'poetry', 'manga', 'comic', 'article'],
  writing: ['write', 'writ', 'blog', 'journal', 'story', 'screenplay', 'author', 'draft', 'poem'],
  fitness: ['gym', 'workout', 'exercis', 'lift', 'weight', 'run', 'jog', 'cardio', 'yoga', 'pilat', 'crossfit', 'train', 'fit', 'hiit', 'stretch', 'pushup', 'squat', 'swim', 'cycl', 'bike', 'marathon', 'hike', 'walk'],
  gaming: ['game', 'gaming', 'play', 'xbox', 'playstation', 'ps5', 'nintendo', 'switch', 'steam', 'minecraft', 'fortnite', 'valorant', 'league', 'lol', 'chess', 'dota', 'csgo', 'overwatch', 'rpg', 'mmo', 'fps', 'roblox', 'apex', 'zelda', 'pokemon'],
  music: ['music', 'song', 'guitar', 'piano', 'drum', 'sing', 'band', 'produc', 'beat', 'dj', 'violin', 'bass', 'ukulele', 'rap', 'compos', 'listen', 'spotify', 'album', 'concert', 'jam'],
  art: ['draw', 'paint', 'sketch', 'art', 'design', 'illustrat', 'photoshop', 'figma', 'animat', 'sculpt', 'craft', 'knit', 'crochet', 'sew', 'pottery', 'photo', 'doodl', 'watercolor', 'procreat'],
  cooking: ['cook', 'bake', 'recip', 'kitchen', 'dinner', 'lunch', 'breakfast', 'meal', 'food', 'eat', 'pasta', 'pizza', 'cake', 'bread', 'grill', 'bbq', 'chef', 'snack', 'brunch'],
  watching: ['watch', 'movi', 'film', 'netflix', 'show', 'seri', 'anime', 'youtube', 'tv', 'episod', 'documentar', 'stream', 'hbo', 'disney', 'cinema'],
  working: ['work', 'job', 'office', 'meeting', 'email', 'spreadsheet', 'excel', 'report', 'project', 'deadline', 'startup', 'business', 'freelanc', 'client', 'present', 'slide', 'pitch'],
  language: ['language', 'spanish', 'french', 'german', 'japanese', 'chines', 'korean', 'italian', 'duolingo', 'english', 'arabic', 'turkish', 'portugues', 'vocab', 'grammar', 'fluent'],
  chilling: ['chill', 'relax', 'bored', 'nothing', 'hang', 'lazy', 'rest', 'couch', 'vibe', 'talk', 'chat', 'lonely'],
  meditation: ['meditat', 'mindful', 'breath', 'journal', 'therap', 'selfcare'],
  cleaning: ['clean', 'laundr', 'tidy', 'organiz', 'declutter', 'dish', 'vacuum', 'chore'],
  outdoors: ['park', 'beach', 'hike', 'camp', 'garden', 'fish', 'climb', 'outdoor', 'nature', 'surf', 'ski', 'snowboard'],
  travel: ['travel', 'trip', 'flight', 'airport', 'vacation', 'explor', 'visit', 'tour', 'commut', 'train', 'bus'],
};

// Very small suffix-stripping stemmer; good enough to align "running"/"runs"/"run".
function stem(word) {
  let w = word;
  if (w.length > 5 && w.endsWith('ies')) w = w.slice(0, -3) + 'i';
  else if (w.length > 4 && w.endsWith('ing')) w = w.slice(0, -3);
  else if (w.length > 4 && w.endsWith('ed')) w = w.slice(0, -2);
  else if (w.length > 3 && w.endsWith('es')) w = w.slice(0, -2);
  else if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss')) w = w.slice(0, -1);
  // "running" -> "runn" -> "run"
  if (w.length > 3 && w[w.length - 1] === w[w.length - 2] && !'lsz'.includes(w[w.length - 1])) {
    w = w.slice(0, -1);
  }
  return w;
}

function tokenize(text) {
  return String(text || '')
    .normalize('NFC')
    .toLowerCase()
    // Letters and digits of any script (defect D3: "satranç" used to become "satran", and
    // Japanese or Russian text vanished entirely).
    .replace(/[^\p{L}\p{M}\p{N}\s']/gu, ' ')
    .split(/\s+/)
    .map((t) => t.replace(/'/g, ''))
    .filter((t) => t && !STOPWORDS.has(t));
}

// Longer words that are nearly the same spelling count as a trigger hit ("progamming").
function nearlySame(w, trig) {
  return w.length >= 6 && trig.length >= 6 && jaccard(trigrams([w]), trigrams([trig])) >= 0.45;
}

function categoriesFor(stems, rawTokens) {
  const found = new Set();
  const words = new Set([...stems, ...rawTokens]);
  for (const [cat, triggers] of Object.entries(CATEGORIES)) {
    for (const trig of triggers) {
      for (const w of words) {
        if (w === trig || (trig.length >= 4 && w.startsWith(trig)) || (w.length >= 4 && trig.startsWith(w)) || nearlySame(w, trig)) {
          found.add(cat);
          break;
        }
      }
      if (found.has(cat)) break;
    }
  }
  return found;
}

function trigrams(stems) {
  const grams = new Set();
  for (const s of stems) {
    const padded = `  ${s} `;
    for (let i = 0; i < padded.length - 2; i++) grams.add(padded.slice(i, i + 3));
  }
  return grams;
}

function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
}

function cosine(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / Math.sqrt(a.size * b.size);
}

// Precompute everything needed for scoring, so each prompt is analysed once.
function analyze(text) {
  const raw = tokenize(text);
  const stems = raw.map(stem);
  return {
    stems: new Set(stems),
    categories: categoriesFor(stems, raw),
    grams: trigrams(stems),
  };
}

// Meaning similarity from embeddings (see embeddings.js), mapped onto the 0-1 score scale.
// For this model, unrelated activities sit below ~0.25 cosine and paraphrases above ~0.75.
const SEMANTIC_LOW = 0.25;
const SEMANTIC_HIGH = 0.75;

function semantic(a, b) {
  if (!a.vec || !b.vec) return 0;
  let dot = 0;
  for (let i = 0; i < a.vec.length; i++) dot += a.vec[i] * b.vec[i];
  return Math.max(0, Math.min(1, (dot - SEMANTIC_LOW) / (SEMANTIC_HIGH - SEMANTIC_LOW)));
}

// The better of word overlap and meaning: words catch exact phrases and typos, meaning catches
// synonyms, slang and other languages.
function score(a, b) {
  return Math.max(lexical(a, b), semantic(a, b));
}

function lexical(a, b) {
  const cat = jaccard(a.categories, b.categories);
  const kw = cosine(a.stems, b.stems);
  const fuzzy = jaccard(a.grams, b.grams);
  let s = 0.45 * cat + 0.35 * kw + 0.2 * fuzzy;
  // Exact same wording should always be a top match.
  if (kw === 1 && a.stems.size) s = Math.max(s, 0.95);
  // Sharing a category with only light wording overlap is still a meaningful match.
  if (cat > 0) s = Math.max(s, 0.3 + 0.4 * cat);
  return Math.min(1, s);
}

module.exports = { analyze, score, lexical, semantic, tokenize, stem };

prefs.js.source:
// Match preferences: who someone wants to meet (gender, age, country, language) and how (video,
// voice, chat). Matching is mutual: two people only see each other when each fits the other's
// filters and they share at least one mode.
const { GENDERS, AGE_BANDS, MODES, COUNTRIES, LANGUAGES, MAX_LANGUAGES } = require('./public/prefs-data');

const DEFAULTS = Object.freeze({ genders: [], ages: [], countries: [], languages: [], modes: [...MODES] });

const pick = (list, allowed, max = allowed.length) => [...new Set((Array.isArray(list) ? list : []).filter((x) => allowed.includes(x)))].slice(0, max);

// Cleans preferences from a request or the database. Empty lists mean "anyone".
function clean(p = {}) {
  const modes = pick(p.modes, MODES);
  return {
    genders: pick(p.genders, GENDERS),
    ages: pick(p.ages, Object.keys(AGE_BANDS)),
    countries: pick(p.countries, COUNTRIES, 20),
    languages: pick(p.languages, LANGUAGES, 10),
    modes: modes.length ? MODES.filter((m) => modes.includes(m)) : [...MODES],
  };
}

function parse(json) {
  if (!json) return { ...DEFAULTS, modes: [...MODES] };
  try {
    return clean(JSON.parse(json));
  } catch {
    return { ...DEFAULTS, modes: [...MODES] };
  }
}

function ageFrom(dob, today = new Date()) {
  const d = new Date(`${dob}T00:00:00Z`);
  if (Number.isNaN(d.getTime())) return null;
  let age = today.getUTCFullYear() - d.getUTCFullYear();
  const m = today.getUTCMonth() - d.getUTCMonth();
  if (m < 0 || (m === 0 && today.getUTCDate() < d.getUTCDate())) age--;
  return age;
}

const parseLanguages = (json) => {
  try { return pick(JSON.parse(json || '[]'), LANGUAGES, MAX_LANGUAGES); } catch { return []; }
};

// What other people's filters are checked against, from an account row.
function facts(row) {
  return {
    gender: row.gender || null,
    age: ageFrom(row.date_of_birth),
    country: row.country || null,
    languages: parseLanguages(row.languages),
  };
}

// Does someone with these facts fit these preferences? Unknown facts only pass "anyone".
function fits(p, f) {
  if (p.genders.length && !p.genders.includes(f.gender)) return false;
  if (p.ages.length && !(f.age != null && p.ages.some((b) => f.age >= AGE_BANDS[b][0] && f.age <= AGE_BANDS[b][1]))) return false;
  if (p.countries.length && !p.countries.includes(f.country)) return false;
  if (p.languages.length && !f.languages.some((l) => p.languages.includes(l))) return false;
  return true;
}

// The richest mode both allow (video > voice > chat), or null if they share none.
function callMode(a, b) {
  return MODES.find((m) => a.prefs.modes.includes(m) && b.prefs.modes.includes(m)) || null;
}

// a and b are { prefs, facts }.
function compatible(a, b) {
  return !!callMode(a, b) && fits(a.prefs, b.facts) && fits(b.prefs, a.facts);
}

// How many filters narrow the search (for the "Filters (3)" button).
function activeCount(p) {
  return ['genders', 'ages', 'countries', 'languages'].filter((k) => p[k].length).length + (p.modes.length < MODES.length ? 1 : 0);
}

module.exports = { DEFAULTS, clean, parse, facts, fits, callMode, compatible, activeCount, parseLanguages, ageFrom, MODES, COUNTRIES, LANGUAGES, MAX_LANGUAGES };

turn.js.source:
const crypto = require('crypto');

// ICE servers handed to each client when a room opens.
//
// TURN uses coturn's "REST API" scheme: credentials are minted here with a secret shared with
// coturn (TURN_SECRET) and expire on their own, so the relay can't be used by anyone who isn't
// currently in a Connecto room.
const TTL_SECONDS = 12 * 60 * 60;
const PUBLIC_STUN = { urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] };

function iceServersFor(accountId) {
  const secret = process.env.TURN_SECRET;
  const host = process.env.TURN_HOST; // IP or hostname for plain TURN on 3478
  if (!secret || !host) return [PUBLIC_STUN];

  const username = `${Math.floor(Date.now() / 1000) + TTL_SECONDS}:${accountId}`;
  const credential = crypto.createHmac('sha1', secret).update(username).digest('base64');
  const urls = [
    `stun:${host}:3478`,
    `turn:${host}:3478?transport=udp`,
    `turn:${host}:3478?transport=tcp`,
  ];
  // TURN over TLS on 443 looks like ordinary HTTPS, so it gets through the strictest firewalls.
  if (process.env.TURN_TLS_HOST) urls.push(`turns:${process.env.TURN_TLS_HOST}:443?transport=tcp`);
  return [PUBLIC_STUN, { urls, username, credential }];
}

module.exports = { iceServersFor };

test/property/invariants.test.js.source:
// Property-based tests (fast-check): laws that must hold for every input, not just chosen examples.
// Each property is checked on 1000 generated inputs (PROP_RUNS overrides); a failure is shrunk to a
// minimal counterexample and the seed is printed so it can be replayed.
process.env.DB_PATH = ':memory:';
const test = require('node:test');
const assert = require('node:assert');
const fc = require('fast-check');
const { analyze, score, lexical, tokenize, stem } = require('../../matcher');
const prefs = require('../../prefs');
const auth = require('../../auth');

const RUNS = Number(process.env.PROP_RUNS) || 1000;
// Activity-like text: real words, typos, other scripts, emoji and junk.
const word = fc.oneof(
  fc.constantFrom('coding', 'gym', 'chess', 'reading', 'satranç', 'çalışıyorum', '勉強', 'книгу', 'running', 'cook', 'the', 'I', "I'm", '🙂', '!!!'),
  fc.string({ minLength: 1, maxLength: 12 }),
  fc.stringMatching(/^[a-z]{1,12}$/),
);
const activity = fc.array(word, { maxLength: 8 }).map((ws) => ws.join(' '));

test('P-MAT-1: scores are always within [0, 1]', () => {
  fc.assert(fc.property(activity, activity, (a, b) => {
    const s = score(analyze(a), analyze(b));
    return s >= 0 && s <= 1;
  }), { numRuns: RUNS });
});

test('P-MAT-2: scoring is symmetric', () => {
  fc.assert(fc.property(activity, activity, (a, b) => score(analyze(a), analyze(b)) === score(analyze(b), analyze(a))), { numRuns: RUNS });
});

test('P-MAT-3: any text with at least one meaningful word scores >= 0.95 against itself', () => {
  fc.assert(fc.property(activity, (a) => {
    fc.pre(tokenize(a).length > 0);
    return lexical(analyze(a), analyze(a)) >= 0.95;
  }), { numRuns: RUNS });
});

test('P-MAT-4: case and surrounding punctuation never change the score', () => {
  fc.assert(fc.property(activity, activity, (a, b) => {
    const base = score(analyze(a), analyze(b));
    return score(analyze(`  ${a.toUpperCase()}?! `), analyze(b)) === base || a.toUpperCase().toLowerCase() !== a.toLowerCase();
  }), { numRuns: RUNS });
});

test('P-MAT-5: tokenize is idempotent and stem never lengthens a word', () => {
  fc.assert(fc.property(activity, (a) => {
    const t = tokenize(a);
    assert.deepStrictEqual(tokenize(t.join(' ')), t);
    for (const w of t) assert.ok(stem(w).length <= w.length);
    return true;
  }), { numRuns: RUNS });
});

const prefsArb = fc.record({
  genders: fc.array(fc.constantFrom('woman', 'man', 'nonbinary', 'robot', 7), { maxLength: 4 }),
  ages: fc.array(fc.constantFrom('18-25', '26-35', '36-45', '46+', '0-1'), { maxLength: 4 }),
  countries: fc.array(fc.constantFrom('TR', 'GB', 'US', 'XX'), { maxLength: 4 }),
  languages: fc.array(fc.constantFrom('en', 'tr', 'fr', 'zz'), { maxLength: 4 }),
  modes: fc.array(fc.constantFrom('video', 'voice', 'chat', 'fax'), { maxLength: 4 }),
}, { requiredKeys: [] });
const factsArb = fc.record({
  gender: fc.constantFrom('woman', 'man', 'nonbinary', 'other', null),
  age: fc.option(fc.integer({ min: 18, max: 110 })),
  country: fc.constantFrom('TR', 'GB', 'US', null),
  languages: fc.subarray(['en', 'tr', 'fr']),
});
const sideArb = fc.record({ prefs: prefsArb.map((p) => prefs.clean(p)), facts: factsArb });

test('P-PREF-1: clean is idempotent and only ever returns allowed values', () => {
  fc.assert(fc.property(fc.oneof(prefsArb, fc.anything()), (raw) => {
    const once = prefs.clean(raw && typeof raw === 'object' ? raw : {});
    assert.deepStrictEqual(prefs.clean(once), once);
    assert.ok(once.modes.length >= 1 && once.modes.every((m) => prefs.MODES.includes(m)));
    assert.ok(once.countries.every((c) => prefs.COUNTRIES.includes(c)));
    return true;
  }), { numRuns: RUNS });
});

test('P-PREF-2: compatibility is symmetric, and nobody with no filters is ever excluded by filters', () => {
  fc.assert(fc.property(sideArb, sideArb, (a, b) => {
    assert.strictEqual(prefs.compatible(a, b), prefs.compatible(b, a));
    assert.ok(prefs.fits(prefs.clean({}), b.facts));
    return true;
  }), { numRuns: RUNS });
});

test('P-PREF-3: adding a filter can only shrink the set of people you fit with (monotonic)', () => {
  fc.assert(fc.property(prefsArb, factsArb, fc.constantFrom('woman', 'man'), (p, f, g) => {
    const loose = prefs.clean(p);
    const strict = prefs.clean({ ...p, genders: [...(p.genders || []).filter((x) => x !== g)].length ? p.genders.filter((x) => x !== g) : [g === 'woman' ? 'man' : 'woman'] });
    // If the strict filter accepts someone, a looser one that includes everything the strict one does must too.
    if (!loose.genders.length && prefs.fits(strict, f)) assert.ok(prefs.fits(loose, f));
    return true;
  }), { numRuns: RUNS });
});

const regArb = fc.record({
  firstName: fc.oneof(fc.string({ maxLength: 60 }), fc.constantFrom('Ada', 'Çağla', "O'Neil"), fc.anything()),
  lastName: fc.oneof(fc.string({ maxLength: 60 }), fc.constant('Lovelace'), fc.anything()),
  email: fc.oneof(fc.emailAddress(), fc.string(), fc.anything()),
  password: fc.oneof(fc.string({ maxLength: 140 }), fc.constant('hunter22abc'), fc.anything()),
  dateOfBirth: fc.oneof(fc.date({ min: new Date('1890-01-01'), max: new Date('2030-01-01') }).map((d) => (Number.isNaN(d.getTime()) ? 'x' : d.toISOString().slice(0, 10))), fc.string(), fc.anything()),
  gender: fc.oneof(fc.constantFrom('woman', 'man', 'other', 'robot', null), fc.anything()),
  avatar: fc.oneof(fc.constant(undefined), fc.constant('data:image/png;base64,AAAA'), fc.anything()),
  acceptTerms: fc.oneof(fc.constant(true), fc.anything()),
}, { requiredKeys: [] });

test('P-AUTH-1: validation never throws, and anything it accepts satisfies every rule (SR1, FR1)', () => {
  const today = new Date();
  fc.assert(fc.property(regArb, (body) => {
    const { errors, value } = auth.validateRegistration(body);
    if (Object.keys(errors).length) return true;
    // Accepted: check the requirements directly, independently of the implementation.
    assert.ok(value.firstName.length >= 1 && value.firstName.length <= 50);
    assert.ok(value.email.length <= 254 && value.email === value.email.toLowerCase() && value.email.includes('@'));
    assert.ok(value.password.length >= 8 && value.password.length <= 128 && /\d/.test(value.password) && /[A-Za-z]/.test(value.password));
    const dob = new Date(`${value.dateOfBirth}T00:00:00Z`);
    const eighteenth = new Date(Date.UTC(dob.getUTCFullYear() + 18, dob.getUTCMonth(), dob.getUTCDate()));
    // Born on 29 Feb: the 18th birthday is 1 March in a non-leap year (Date.UTC rolls over the same way).
    assert.ok(eighteenth <= today, `${value.dateOfBirth} is under 18`);
    assert.strictEqual(body.acceptTerms, true);
    return true;
  }), { numRuns: RUNS });
});

test('P-AUTH-2: profile validation never throws on arbitrary input', () => {
  fc.assert(fc.property(fc.dictionary(fc.constantFrom('bio', 'city', 'country', 'languages', 'gender', 'timezone', 'interests'), fc.anything()), (body) => {
    const { errors, value } = auth.validateProfile(body);
    return typeof errors === 'object' && typeof value === 'object';
  }), { numRuns: RUNS });
});

test('P-AUTH-3: cookie parsing never throws on any header string (D1)', () => {
  fc.assert(fc.property(fc.string({ unit: 'binary' }), (h) => typeof auth.parseCookies(h) === 'object'), { numRuns: RUNS });
});

