// Admin review of reports (FR7, SR2): the moderation branches the other suites did not reach
// (coverage gap in safety.js found in docs/evaluation.md: dismiss, unknown action, status filter).
const test = require('node:test');
const assert = require('node:assert');
const { start, stop, request, signedInSocket, call } = require('../support/helpers');

let base;
test.before(async () => { base = await start(); });
test.after(stop);

test('admins list reports by status, dismiss or suspend; others get 403; unknown actions 400', async (t) => {
  const admin = await signedInSocket(base, { firstName: 'Ada', email: 'admin@example.com' });
  const victim = await signedInSocket(base, { firstName: 'Bea' });
  const rude = await signedInSocket(base, { firstName: 'Cal' });
  const other = await signedInSocket(base, { firstName: 'Dov' });
  t.after(() => [admin, victim, rude, other].forEach((x) => x.sock.close()));

  for (const x of [victim, rude, other]) await call(x.sock, 'set-activity', { activity: 'admin test juggling practice' });
  await new Promise((r) => setTimeout(r, 200));
  assert.deepStrictEqual(await call(victim.sock, 'report', { target: rude.sock.id, reason: 'harassment', details: 'rude' }), { ok: true });
  assert.deepStrictEqual(await call(other.sock, 'report', { target: rude.sock.id, reason: 'spam' }), { ok: true });

  assert.strictEqual((await request(base, 'GET', '/api/admin/reports', null, victim.cookie)).status, 403, 'not an admin');
  const open = await request(base, 'GET', '/api/admin/reports?status=open', null, admin.cookie);
  assert.strictEqual(open.status, 200);
  assert.strictEqual(open.body.reports.length, 2);
  assert.strictEqual(open.body.reports[0].reported.totalReporters, 2);
  assert.strictEqual(open.body.reports[0].reported.name.startsWith('Cal'), true, 'admins see full names');

  const [first, second] = open.body.reports;
  const bad = await request(base, 'POST', `/api/admin/reports/${first.id}`, { action: 'ban-forever' }, admin.cookie);
  assert.strictEqual(bad.status, 400);
  assert.strictEqual((await request(base, 'POST', '/api/admin/reports/999999', { action: 'dismiss' }, admin.cookie)).status, 404);

  assert.strictEqual((await request(base, 'POST', `/api/admin/reports/${first.id}`, { action: 'dismiss', note: '  not abusive  ' }, admin.cookie)).status, 200);
  const dismissed = await request(base, 'GET', '/api/admin/reports?status=dismissed', null, admin.cookie);
  assert.deepStrictEqual(dismissed.body.reports.map((r) => [r.id, r.resolutionNote]), [[first.id, 'not abusive']]);

  const suspended = new Promise((r) => rude.sock.once('suspended', r));
  assert.strictEqual((await request(base, 'POST', `/api/admin/reports/${second.id}`, { action: 'suspend' }, admin.cookie)).status, 200);
  await suspended;
  const actioned = await request(base, 'GET', '/api/admin/reports?status=actioned', null, admin.cookie);
  assert.deepStrictEqual(actioned.body.reports.map((r) => r.id), [second.id]);
  const list = await request(base, 'GET', '/api/admin/suspended', null, admin.cookie);
  assert.ok(list.body.users.some((u) => u.name.startsWith('Cal') && /report #/.test(u.reason)));
  assert.strictEqual((await request(base, 'GET', '/api/admin/reports?status=bogus', null, admin.cookie)).body.reports.length, 2, 'unknown status = all');
});

test/unit/usability-analysis.test.js.source:
// The usability analysis tool is part of the acceptance-test instrumentation, so it is tested too.
// Inputs here are synthetic and only check the arithmetic; they are not study results.
const test = require('node:test');
const assert = require('node:assert');
const { sus, adjustedWald, meanCI, median, geomean, parseCsv, analyse } = require('../acceptance/analyse-usability');

test('SUS scoring: best, worst, neutral and invalid answer sets', () => {
  assert.strictEqual(sus([5, 1, 5, 1, 5, 1, 5, 1, 5, 1]), 100);
  assert.strictEqual(sus([1, 5, 1, 5, 1, 5, 1, 5, 1, 5]), 0);
  assert.strictEqual(sus([3, 3, 3, 3, 3, 3, 3, 3, 3, 3]), 50);
  assert.strictEqual(sus([4, 2, 4, 2, 4, 2, 4, 2, 4, 2]), 75);
  assert.strictEqual(sus([5, 1, 5]), null);
  assert.strictEqual(sus([6, 1, 5, 1, 5, 1, 5, 1, 5, 1]), null);
});

test('Adjusted Wald interval for completion rates (hand-computed values)', () => {
  const [lo, hi] = adjustedWald(9, 10);
  assert.ok(Math.abs(lo - 0.574) < 0.005 && Math.abs(hi - 1) < 0.005, `${lo} ${hi}`);
  const [lo2, hi2] = adjustedWald(0, 5);
  assert.strictEqual(lo2, 0);
  assert.ok(hi2 > 0.4 && hi2 < 0.5);
});

test('summary statistics', () => {
  assert.strictEqual(median([5, 1, 3]), 3);
  assert.strictEqual(median([4, 1, 3, 2]), 2.5);
  assert.ok(Math.abs(geomean([1, 100]) - 10) < 1e-9);
  const m = meanCI([60, 70, 80]);
  assert.strictEqual(m.mean, 70);
  assert.ok(Math.abs(m.ci95[0] - (70 - 4.30 * 10 / Math.sqrt(3))) < 1e-9);
});

test('analyse: completion counts one assist as success, two as failure; SUS once per participant', () => {
  const csv = [
    'participant,group,device,task,success,assists,time_s,errors,seq,sus1,sus2,sus3,sus4,sus5,sus6,sus7,sus8,sus9,sus10',
    'p1,G1,phone,T1,1,0,60,0,6,4,2,4,2,4,2,4,2,4,2',
    'p1,G1,phone,T2,1,2,30,1,4,,,,,,,,,,',
    'p2,G2,laptop,T1,1,1,90,1,5,3,3,3,3,3,3,3,3,3,3',
    'p2,G2,laptop,T2,0,0,120,2,2,,,,,,,,,,',
  ].join('\n');
  const r = analyse(parseCsv(csv));
  assert.strictEqual(r.participants, 2);
  assert.strictEqual(r.perTask.T1.completion, 1);
  assert.strictEqual(r.perTask.T2.completion, 0);
  assert.strictEqual(r.perTask.T1.medianTimeS, 75);
  assert.strictEqual(r.perTask.T2.errors, 3);
  assert.strictEqual(r.sus.mean, 62.5);
});

test/unit/turn-mail.test.js.source:
// Unit tests for TURN credentials (turn.js, requirement SR6) and outgoing email (mail.js, FR8).
process.env.MAIL_TRANSPORT = 'memory';
const test = require('node:test');
const assert = require('node:assert');
const crypto = require('crypto');
const { iceServersFor } = require('../../turn');
const mail = require('../../mail');

function withEnv(vars, fn) {
  const saved = Object.fromEntries(Object.keys(vars).map((k) => [k, process.env[k]]));
  for (const [k, v] of Object.entries(vars)) v === undefined ? delete process.env[k] : (process.env[k] = v);
  try { return fn(); } finally {
    for (const [k, v] of Object.entries(saved)) v === undefined ? delete process.env[k] : (process.env[k] = v);
  }
}

test('without a TURN secret or host, only public STUN servers are handed out', () => {
  for (const env of [{ TURN_SECRET: undefined, TURN_HOST: 'h' }, { TURN_SECRET: 's', TURN_HOST: undefined }]) {
    const servers = withEnv(env, () => iceServersFor(7));
    assert.strictEqual(servers.length, 1);
    assert.ok(servers[0].urls.every((u) => u.startsWith('stun:stun')));
  }
});

test('TURN credentials: "<expiry>:<account>" signed with HMAC-SHA1 of the shared secret, valid 12 hours', () => {
  const real = Date.now;
  Date.now = () => 1_800_000_000_000;
  try {
    const [, turn] = withEnv({ TURN_SECRET: 'sekret', TURN_HOST: '203.0.113.7', TURN_TLS_HOST: undefined }, () => iceServersFor(42));
    assert.strictEqual(turn.username, `${1_800_000_000 + 12 * 3600}:42`);
    assert.strictEqual(turn.credential, crypto.createHmac('sha1', 'sekret').update(turn.username).digest('base64'));
    assert.deepStrictEqual(turn.urls, ['stun:203.0.113.7:3478', 'turn:203.0.113.7:3478?transport=udp', 'turn:203.0.113.7:3478?transport=tcp']);
    const [, tls] = withEnv({ TURN_SECRET: 'sekret', TURN_HOST: 'h', TURN_TLS_HOST: 'turn.example.com' }, () => iceServersFor(42));
    assert.strictEqual(tls.urls.at(-1), 'turns:turn.example.com:443?transport=tcp');
  } finally {
    Date.now = real;
  }
});

test('emails: user-supplied text is HTML-escaped in the HTML part but readable in the text part', async () => {
  await mail.sendVerificationEmail({ email: 'x@example.com', first_name: '<img src=x onerror=alert(1)>' }, 'http://localhost/?verify=abc');
  const m = mail.outbox.at(-1);
  assert.strictEqual(m.to, 'x@example.com');
  assert.ok(!m.html.includes('<img src=x'), 'escaped in HTML');
  assert.ok(m.html.includes('&lt;img src=x onerror=alert(1)&gt;'));
  assert.ok(m.text.includes('Welcome, <img src=x onerror=alert(1)>!'));
  assert.ok(m.text.includes('http://localhost/?verify=abc'));
});

test('password reset and admin report emails carry the right subject and link', async () => {
  await mail.sendPasswordResetEmail({ email: 'r@example.com', first_name: 'Rae' }, 'http://localhost/?reset=t0k');
  assert.match(mail.outbox.at(-1).subject, /Reset your Connecto password/);
  assert.ok(mail.outbox.at(-1).text.includes('?reset=t0k'));
  await mail.sendAdminReportEmail(['a@example.com', 'b@example.com'], { reportedName: 'Bo X', reportedEmail: 'bo@example.com', reason: 'Spam', details: '', reporters: 1, autoSuspended: false });
  const admin = mail.outbox.at(-1);
  assert.strictEqual(admin.to, 'a@example.com, b@example.com');
  assert.strictEqual(admin.subject, 'New report: Bo X');
  assert.match(admin.text, /1 person has reported/);
});

test('connect notices: one subject per kind, times shown in the recipient\'s time zone (or UTC)', async () => {
  const at = Date.UTC(2026, 10, 10, 18, 0);
  const kinds = ['message', 'proposed', 'scheduled', 'reminder', 'request', 'accepted', 'match'];
  const subjects = new Set();
  for (const kind of kinds) {
    await mail.sendConnectNotice({ email: 'n@example.com', first_name: 'Nil', timezone: 'Europe/Istanbul' }, { kind, name: 'Ata', activity: 'chess', at });
    subjects.add(mail.outbox.at(-1).subject);
  }
  assert.strictEqual(subjects.size, kinds.length);
  assert.ok([...subjects].some((s) => s.includes('9:00 PM')), 'Istanbul is UTC+3');
  await mail.sendConnectNotice({ email: 'n@example.com', first_name: 'Nil', timezone: 'Not/AZone' }, { kind: 'scheduled', name: 'Ata', at });
  assert.match(mail.outbox.at(-1).subject, /18:00:00 GMT|6:00 PM/, 'invalid zone falls back');
  assert.ok(mail.outbox.at(-1).text.includes('/#connects'));
});

test/unit/safety.test.js.source:
// Unit tests for safety.js (reports, auto-suspension, blocks), requirements FR7, SR2, SR3.
// Test cases come from the category-partition specification in docs/test-specs/report-category-partition.md
// (TS-REP-n ids in the test names). The database is an in-memory SQLite (test/support/db-fixture.js).
process.env.ADMIN_EMAILS = 'admin@example.com';
const test = require('node:test');
const assert = require('node:assert');
const { db, makeUser, atTime } = require('../support/db-fixture');
const safety = require('../../safety');
const { outbox } = require('../../mail');

const HOUR = 60 * 60 * 1000;
const report = (reporterId, reportedId, extra = {}) =>
  safety.createReport({ reporterId, reportedId, reason: 'spam', context: 'match', ...extra });
const reportsAbout = (id) => db.prepare('SELECT * FROM reports WHERE reported_id = ?').all(id);
const banned = (id) => db.prepare('SELECT banned_at, ban_reason FROM users WHERE id = ?').get(id);

test('TS-REP-1: every listed reason is accepted', () => {
  for (const reason of Object.keys(safety.REASONS)) {
    // A fresh person each time: three reports about one person would (correctly) suspend them.
    assert.deepStrictEqual(report(makeUser(), makeUser(), { reason }), { ok: true, autoSuspended: false }, reason);
  }
});

test('D2 / TS-REP-2 [error]: unknown, missing and non-string reasons are refused', () => {
  const [a, b] = [makeUser(), makeUser()];
  for (const reason of ['', 'SPAM', 'rude', undefined, null, 42, ['spam'], { spam: 1 }]) {
    assert.match(report(a, b, { reason }).error || '', /Choose a reason/, String(reason));
  }
  assert.strictEqual(reportsAbout(b).length, 0);
});

test('D2 / TS-REP-3 [error]: inherited object keys are not valid reasons', () => {
  const [a, b] = [makeUser(), makeUser()];
  for (const reason of ['constructor', '__proto__', 'toString', 'hasOwnProperty', 'valueOf']) {
    assert.match(report(a, b, { reason }).error || '', /Choose a reason/, reason);
  }
  assert.strictEqual(reportsAbout(b).length, 0, 'nothing stored');
});

test('TS-REP-4 [error]: you cannot report yourself', () => {
  const a = makeUser();
  assert.match(report(a, a).error, /report yourself/);
});

test('TS-REP-5: details are whitespace-collapsed, trimmed and cut at 500 characters', () => {
  const [a, b, c, d] = [makeUser(), makeUser(), makeUser(), makeUser()];
  report(a, b, { details: '  line one\n\n\tline   two  ' });
  assert.strictEqual(reportsAbout(b)[0].details, 'line one line two');
  report(a, c, { details: 'x'.repeat(501) });
  assert.strictEqual(reportsAbout(c)[0].details.length, 500);
  report(a, d, { details: '   ' });
  assert.strictEqual(reportsAbout(d)[0].details, null, 'blank details stored as NULL');
});

test('TS-REP-6: a second open report about the same person updates the first (one per pair)', () => {
  const [a, b] = [makeUser(), makeUser()];
  report(a, b, { reason: 'spam', details: 'first' });
  report(a, b, { reason: 'harassment', details: 'second' });
  const rows = reportsAbout(b);
  assert.strictEqual(rows.length, 1);
  assert.strictEqual(rows[0].reason, 'harassment');
  assert.strictEqual(rows[0].details, 'second');
});

test('TS-REP-7: the transcript keeps only the last 100 messages', () => {
  const [a, b] = [makeUser(), makeUser()];
  const transcript = Array.from({ length: 130 }, (_, i) => ({ name: 'x', text: `m${i}`, at: i }));
  report(a, b, { context: 'call', transcript });
  const kept = JSON.parse(reportsAbout(b)[0].transcript);
  assert.strictEqual(kept.length, 100);
  assert.strictEqual(kept[0].text, 'm30');
  assert.strictEqual(kept.at(-1).text, 'm129');
});

test('TS-REP-8 (boundary): the 10th report in an hour is accepted, the 11th refused, and the limit resets after an hour', async () => {
  const reporter = makeUser();
  const t0 = Date.UTC(2026, 10, 1, 12);
  await atTime(t0, () => {
    for (let i = 0; i < 10; i++) assert.ok(report(reporter, makeUser()).ok, `report ${i + 1}`);
    assert.match(report(reporter, makeUser()).error, /a lot of reports/);
  });
  await atTime(t0 + HOUR + 1, () => assert.ok(report(reporter, makeUser()).ok, 'window has passed'));
});

test('TS-REP-9 (boundary): reports from 2 people do not suspend; the 3rd distinct person within 24h does', () => {
  const target = makeUser();
  const before = outbox.length;
  assert.strictEqual(report(makeUser(), target).autoSuspended, false);
  assert.strictEqual(report(makeUser(), target).autoSuspended, false);
  assert.strictEqual(banned(target).banned_at, null);
  assert.strictEqual(report(makeUser(), target).autoSuspended, true);
  assert.ok(banned(target).banned_at);
  assert.match(banned(target).ban_reason, /reported by 3 people/);
  const mails = outbox.slice(before).filter((m) => m.to === 'admin@example.com');
  assert.strictEqual(mails.length, 3, 'admins are emailed about each new report');
  assert.match(mails.at(-1).subject, /^\[Auto-suspended\]/);
});

test('TS-REP-10: the same person reporting twice counts once towards auto-suspension', () => {
  const target = makeUser();
  const a = makeUser();
  report(a, target);
  report(a, target, { reason: 'hate' });
  report(makeUser(), target);
  assert.strictEqual(banned(target).banned_at, null);
});

test('TS-REP-11 (boundary): reports older than 24 hours do not count towards auto-suspension', async () => {
  const target = makeUser();
  const t0 = Date.UTC(2026, 10, 2, 12);
  await atTime(t0, () => { report(makeUser(), target); report(makeUser(), target); });
  await atTime(t0 + 24 * HOUR + 1, () => {
    assert.strictEqual(report(makeUser(), target).autoSuspended, false);
  });
  assert.strictEqual(banned(target).banned_at, null);
});

test('TS-REP-12: suspension deletes the account\'s sessions and calls the realtime handler once', () => {
  const target = makeUser();
  db.prepare('INSERT INTO sessions (token_hash, user_id, created_at, expires_at) VALUES (?, ?, ?, ?)').run(`h${target}`, target, 0, Date.now() + HOUR);
  const kicked = [];
  safety.setSuspendHandler((id) => kicked.push(id));
  for (let i = 0; i < 4; i++) report(makeUser(), target);
  assert.deepStrictEqual(kicked, [target], 'already-suspended accounts are not suspended again');
  assert.strictEqual(db.prepare('SELECT COUNT(*) AS n FROM sessions WHERE user_id = ?').get(target).n, 0);
  safety.setSuspendHandler(() => {});
});

test('blocks are symmetric, self-blocks are ignored, and unblocking keeps a reverse block in force', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  safety.block(a, a);
  assert.strictEqual(safety.isBlocked(a, a), false);
  safety.block(a, b);
  assert.ok(safety.isBlocked(a, b) && safety.isBlocked(b, a), 'both directions');
  assert.strictEqual(safety.isBlocked(a, c), false);
  safety.block(b, a); // both blocked each other
  safety.unblock(a, b);
  assert.ok(safety.isBlocked(a, b), 'b still blocks a');
  safety.unblock(b, a);
  assert.strictEqual(safety.isBlocked(a, b), false);
});

test('admins are verified, unsuspended accounts listed in ADMIN_EMAILS (case-insensitive)', () => {
  const user = (o) => ({ email: 'Admin@Example.com', email_verified_at: 1, banned_at: null, ...o });
  assert.strictEqual(safety.isAdmin(user()), true);
  assert.strictEqual(safety.isAdmin(user({ email_verified_at: null })), false);
  assert.strictEqual(safety.isAdmin(user({ banned_at: 1 })), false);
  assert.strictEqual(safety.isAdmin(user({ email: 'someone@example.com' })), false);
  assert.strictEqual(safety.isAdmin(null), false);
});

test/unit/prefs.pairwise.test.js.source:
// Combinatorial testing of match preferences (requirement FR3: "two people only see each other when
// each fits the other's filters and they share at least one call mode").
//  - Pairwise (all-pairs) suite over 10 parameters generated by test/support/pairwise.js; the full
//    cartesian product would be 196,830 cases.
//  - Oracle: an independent restatement of the requirement (oracleFits/oracleCompatible below),
//    written from the requirement text, not from prefs.js.
//  - Boundary values of every age band (BV-AGE).
const test = require('node:test');
const assert = require('node:assert');
const prefs = require('../../prefs');
const { pairwise, missingPairs } = require('../support/pairwise');

const BANDS = { '18-25': [18, 25], '26-35': [26, 35], '36-45': [36, 45], '46+': [46, Infinity] };
function oracleFits(p, f) {
  const ok = (filter, test) => filter.length === 0 || test();
  return ok(p.genders, () => p.genders.includes(f.gender))
    && ok(p.ages, () => f.age != null && p.ages.some((b) => f.age >= BANDS[b][0] && f.age <= BANDS[b][1]))
    && ok(p.countries, () => p.countries.includes(f.country))
    && ok(p.languages, () => f.languages.some((l) => p.languages.includes(l)));
}
const oracleCompatible = (a, b) =>
  a.prefs.modes.some((m) => b.prefs.modes.includes(m)) && oracleFits(a.prefs, b.facts) && oracleFits(b.prefs, a.facts);

// Parameters: A's filters and modes, B's facts and modes. B has no filters here (tested separately).
const PARAMS = {
  genderFilter: [[], ['woman'], ['man', 'nonbinary']],
  gender: ['woman', 'man', 'nonbinary', 'other', null],
  ageFilter: [[], ['18-25'], ['26-35', '46+']],
  age: [18, 25, 26, 45, 46, null],
  countryFilter: [[], ['TR'], ['GB', 'TR']],
  country: ['TR', 'GB', null],
  languageFilter: [[], ['en'], ['fr', 'tr']],
  languages: [[], ['en'], ['tr', 'de']],
  modesA: [['video', 'voice', 'chat'], ['voice', 'chat'], ['chat']],
  modesB: [['video', 'voice', 'chat'], ['video'], ['voice']],
};

const cases = pairwise(PARAMS);

test('the generated suite covers every pair of parameter values', () => {
  assert.deepStrictEqual(missingPairs(PARAMS, cases), []);
  assert.ok(cases.length < 60, `${cases.length} cases instead of 196,830`);
});

test('pairwise: prefs.fits and prefs.compatible agree with the oracle on every generated case', () => {
  for (const c of cases) {
    const a = {
      prefs: prefs.clean({ genders: c.genderFilter, ages: c.ageFilter, countries: c.countryFilter, languages: c.languageFilter, modes: c.modesA }),
      facts: { gender: 'woman', age: 30, country: 'GB', languages: ['en'] },
    };
    const b = { prefs: prefs.clean({ modes: c.modesB }), facts: { gender: c.gender, age: c.age, country: c.country, languages: c.languages } };
    const label = JSON.stringify(c);
    assert.strictEqual(prefs.fits(a.prefs, b.facts), oracleFits(a.prefs, b.facts), `fits ${label}`);
    assert.strictEqual(prefs.compatible(a, b), oracleCompatible(a, b), `compatible ${label}`);
    assert.strictEqual(prefs.compatible(a, b), prefs.compatible(b, a), `symmetric ${label}`);
  }
});

test('BV-AGE: each age band includes both of its end points and excludes the neighbours', () => {
  const f = (age) => ({ gender: null, age, country: null, languages: [] });
  for (const [band, [lo, hi]] of Object.entries({ '18-25': [18, 25], '26-35': [26, 35], '36-45': [36, 45], '46+': [46, 150] })) {
    const p = prefs.clean({ ages: [band] });
    assert.ok(prefs.fits(p, f(lo)) && prefs.fits(p, f(hi)), `${band} contains ${lo} and ${hi}`);
    assert.ok(!prefs.fits(p, f(lo - 1)), `${band} excludes ${lo - 1}`);
    assert.ok(!prefs.fits(p, f(hi + 1)), `${band} excludes ${hi + 1}`);
  }
  assert.ok(!prefs.fits(prefs.clean({ ages: ['46+'] }), f(null)), 'unknown age only passes "anyone"');
});

test('callMode picks the richest shared mode (video > voice > chat)', () => {
  const side = (modes) => ({ prefs: prefs.clean({ modes }) });
  assert.strictEqual(prefs.callMode(side(['chat', 'video']), side(['video', 'chat'])), 'video');
  assert.strictEqual(prefs.callMode(side(['chat', 'voice']), side(['voice', 'chat'])), 'voice');
  assert.strictEqual(prefs.callMode(side(['chat']), side(['chat'])), 'chat');
  assert.strictEqual(prefs.callMode(side(['video']), side(['voice'])), null);
});

test('clean: unknown values dropped, duplicates removed, list caps (20 countries, 10 languages), modes ordered', () => {
  const c = prefs.clean({
    genders: ['man', 'man', 'robot'], ages: ['18-25', '99-100'], countries: prefs.COUNTRIES.slice(0, 25),
    languages: prefs.LANGUAGES.slice(0, 12), modes: ['chat', 'video', 'smoke-signals'],
  });
  assert.deepStrictEqual(c.genders, ['man']);
  assert.deepStrictEqual(c.ages, ['18-25']);
  assert.strictEqual(c.countries.length, 20);
  assert.strictEqual(c.languages.length, 10);
  assert.deepStrictEqual(c.modes, ['video', 'chat'], 'kept in richest-first order');
  assert.deepStrictEqual(prefs.clean({ genders: 'man' }).genders, [], 'not a list');
  assert.deepStrictEqual(prefs.clean().modes, ['video', 'voice', 'chat']);
});

test('parse falls back to defaults for missing or corrupt JSON; activeCount counts narrowing filters', () => {
  assert.deepStrictEqual(prefs.parse(null), { ...prefs.DEFAULTS, modes: ['video', 'voice', 'chat'] });
  assert.deepStrictEqual(prefs.parse('{not json'), prefs.parse(null));
  assert.deepStrictEqual(prefs.parse('{"genders":["woman"]}').genders, ['woman']);
  assert.strictEqual(prefs.activeCount(prefs.clean({})), 0);
  assert.strictEqual(prefs.activeCount(prefs.clean({ genders: ['man'], languages: ['en'], modes: ['chat'] })), 3);
});

test('facts are read from an account row; languages capped at 5 and corrupt JSON ignored', () => {
  const now = new Date();
  const dob = `${now.getUTCFullYear() - 30}-01-01`;
  const f = prefs.facts({ gender: 'woman', date_of_birth: dob, country: 'TR', languages: '["tr","en","xx","fr","de","es","it"]' });
  assert.strictEqual(f.age, 30, 'born 1 January, 30 years ago');
  assert.deepStrictEqual(f.languages, ['tr', 'en', 'fr', 'de', 'es']);
  assert.deepStrictEqual(prefs.facts({ date_of_birth: 'bad', languages: '{' }), { gender: null, age: null, country: null, languages: [] });
  assert.strictEqual(prefs.ageFrom('2008-02-29', new Date('2026-02-28T12:00:00Z')), 17);
  assert.strictEqual(prefs.ageFrom('2008-02-29', new Date('2026-03-01T12:00:00Z')), 18);
});

test/unit/mutation-driven.test.js.source:
// Tests added after the first mutation run (reports/test-runs/stryker-run-1.txt, 56.8%): each MK-n test kills
// surviving mutants that showed a real weakness in the earlier tests (docs/evaluation.md section 3).
// Weaknesses found: one-sided time-window tests, no exact score oracles (only thresholds, hidden by a clamp),
// a tautological oracle (DEFAULTS compared with itself), untested regex anchors and normalised values.
process.env.ADMIN_EMAILS = 'admin@example.com';
const test = require('node:test');
const assert = require('node:assert');
const { db, makeUser, atTime } = require('../support/db-fixture');
const matcher = require('../../matcher');
const prefs = require('../../prefs');
const safety = require('../../safety');
const bg = require('../../background');
const chat = require('../../chat');
const friends = require('../../friends');
const auth = require('../../auth');
const { iceServersFor } = require('../../turn');
const { outbox } = require('../../mail');

const HOUR = 3600e3;
const DAY = 24 * HOUR;
const T0 = Date.UTC(2026, 10, 20, 12);

// ---- matcher: exact oracles, computed by hand ----

test('MK-1: exact word score with no shared category: 0.35 x keyword cosine + 0.2 x trigram Jaccard', () => {
  // keywords {xylo,quartz} vs {xylo,zebra}: cosine 1/2; trigrams 5 shared of 12 + 11 -> 5/18; no category.
  const s = matcher.lexical(matcher.analyze('xylo quartz'), matcher.analyze('xylo zebra'));
  assert.ok(Math.abs(s - (0.35 * 0.5 + 0.2 * (5 / 18))) < 1e-12, String(s));
});

test('MK-2: the same-category floor is exactly 0.3 + 0.4 x category overlap', () => {
  // gym {fitness} vs workout {fitness, working}: overlap 1/2, no shared words or trigrams.
  assert.strictEqual(matcher.lexical(matcher.analyze('gym'), matcher.analyze('workout')), 0.5);
});

test('MK-3: category triggers: exact word, a word starting with a 4-letter trigger, a 4-letter prefix of a trigger', () => {
  assert.deepStrictEqual([...matcher.analyze('codebase').categories], ['coding']); // starts with "code"
  assert.deepStrictEqual([...matcher.analyze('prog').categories], ['coding']); // prefix of "program"
  assert.deepStrictEqual([...matcher.analyze('pro').categories], [], 'three letters are too short to be a prefix');
  assert.deepStrictEqual([...matcher.analyze('ding').categories], [], 'a suffix of a trigger ("coding") does not count');
});

test('MK-4: punctuation separates words; a meaning score needs vectors on both sides', () => {
  assert.deepStrictEqual(matcher.tokenize('coding,gaming'), ['coding', 'gaming']);
  const a = matcher.analyze('x'), b = matcher.analyze('y');
  a.vec = Float32Array.from([1, 0]);
  assert.strictEqual(matcher.semantic(a, b), 0);
  assert.strictEqual(matcher.semantic(b, a), 0);
});

// ---- prefs: literal oracles instead of comparing the module with itself ----

test('MK-5: defaults are "anyone" with every mode (literal oracle)', () => {
  const expected = { genders: [], ages: [], countries: [], languages: [], modes: ['video', 'voice', 'chat'] };
  assert.deepStrictEqual(prefs.parse(null), expected);
  assert.deepStrictEqual(prefs.parse(''), expected);
  assert.deepStrictEqual({ ...prefs.DEFAULTS }, expected);
});

test('MK-6: ages around a birthday in the same month, and filters with unknown or matching facts', () => {
  assert.strictEqual(prefs.ageFrom('2000-11-20', new Date('2026-11-19T12:00:00Z')), 25);
  assert.strictEqual(prefs.ageFrom('2000-11-20', new Date('2026-11-20T12:00:00Z')), 26);
  assert.strictEqual(prefs.ageFrom('2000-11-20', new Date('2026-12-01T12:00:00Z')), 26);
  const f = (o) => ({ gender: null, age: null, country: null, languages: [], ...o });
  assert.strictEqual(prefs.fits(prefs.clean({ ages: ['18-25'] }), f({ age: 20 })), true);
  assert.strictEqual(prefs.fits(prefs.clean({ ages: ['18-25'] }), f({ age: null })), false);
  assert.strictEqual(prefs.fits(prefs.clean({ languages: ['tr'] }), f({ languages: ['en', 'tr'] })), true);
  assert.strictEqual(prefs.fits(prefs.clean({ languages: ['tr'] }), f({ languages: ['en'] })), false);
});

// ---- time windows tested on BOTH sides ----

test('MK-7: auto-suspension counts reports from the last 24 h (3rd report 23 h later still suspends)', async () => {
  const target = makeUser();
  await atTime(T0, () => { safety.createReport({ reporterId: makeUser(), reportedId: target, reason: 'spam', context: 'match' }); });
  await atTime(T0 + HOUR, () => { safety.createReport({ reporterId: makeUser(), reportedId: target, reason: 'spam', context: 'match' }); });
  const r = await atTime(T0 + 23 * HOUR, () => safety.createReport({ reporterId: makeUser(), reportedId: target, reason: 'spam', context: 'match' }));
  assert.strictEqual(r.autoSuspended, true);
});

test('MK-8: the report limit window is a full hour (10 reports spread over 59 minutes still block the 11th)', async () => {
  const reporter = makeUser();
  for (let i = 0; i < 10; i++) await atTime(T0 + i * 6 * 60e3, () => safety.createReport({ reporterId: reporter, reportedId: makeUser(), reason: 'spam', context: 'match' }));
  const r = await atTime(T0 + 59 * 60e3, () => safety.createReport({ reporterId: reporter, reportedId: makeUser(), reason: 'spam', context: 'match' }));
  assert.match(r.error, /a lot of reports/);
});

test('MK-9: the daily connect-request limit lasts 24 h, then resets', async () => {
  const a = makeUser();
  await atTime(T0, () => { for (let i = 0; i < 20; i++) bg.request(a, makeUser(), 'x'); });
  await atTime(T0 + 23 * HOUR, () => assert.match(bg.request(a, makeUser(), 'x').error, /a lot of requests/));
  await atTime(T0 + DAY + 1, () => assert.strictEqual(bg.request(a, makeUser(), 'x').status, 'pending'));
});

test('MK-10: "talked recently" lasts exactly 7 days', async () => {
  const [a, b] = [makeUser(), makeUser()];
  await atTime(T0, () => { bg.request(a, b, 'x'); bg.settle(a, b); });
  await atTime(T0 + 7 * DAY - 1, () => assert.strictEqual(bg.talkedRecently(a, b), true));
  await atTime(T0 + 7 * DAY, () => assert.strictEqual(bg.talkedRecently(a, b), false));
});

test('MK-11: notification emails are throttled to one per 3 hours, except urgent ones', async () => {
  const a = makeUser({ email: `notify${Date.now()}@example.com` });
  const mine = () => outbox.filter((m) => m.to.startsWith('notify')).length;
  const before = mine();
  await atTime(T0, () => bg.notify(a, 'request', { name: 'X', activity: 'chess' }));
  await atTime(T0 + 3 * HOUR - 1, () => bg.notify(a, 'request', { name: 'X', activity: 'chess' }));
  await atTime(T0 + 3 * HOUR - 1, () => bg.notify(a, 'reminder', { name: 'X', at: T0 + 4 * HOUR, urgent: true }));
  await atTime(T0 + 3 * HOUR, () => bg.notify(a, 'request', { name: 'X', activity: 'chess' }));
  await new Promise((r) => setImmediate(r));
  assert.strictEqual(mine() - before, 3, 'first, urgent, and the one after 3 h');
  bg.setNotify(a, false);
  await atTime(T0 + 9 * HOUR, () => bg.notify(a, 'request', { name: 'X', activity: 'chess' }));
  await new Promise((r) => setImmediate(r));
  assert.strictEqual(mine() - before, 3, 'turned off');
});

test('MK-12: the DM burst window is 10 s (5 s later the 16th is still refused)', async () => {
  const [a, b] = [makeUser(), makeUser()];
  chat.connect(a, b);
  await atTime(T0, () => { for (let i = 0; i < 15; i++) chat.send(a, b, `m${i}`); });
  await atTime(T0 + 5e3, () => assert.match(chat.send(a, b, 'too soon').error, /too fast/));
});

// ---- boundaries the first suite missed ----

test('MK-13: exactly 3 proposed times are allowed and are sorted; picking at exactly "now" is allowed', async () => {
  const [a, b] = [makeUser(), makeUser()];
  let id;
  await atTime(T0, () => {
    id = bg.request(a, b, 'x').request.id;
    bg.respond(id, b, true);
    const times = [T0 + 3 * HOUR, T0 + HOUR, T0 + 2 * HOUR];
    assert.deepStrictEqual(JSON.parse(bg.propose(id, a, times).proposed_slots), [T0 + HOUR, T0 + 2 * HOUR, T0 + 3 * HOUR]);
  });
  await atTime(T0 + HOUR, () => assert.strictEqual(bg.pick(id, b, T0 + HOUR).meeting_at, T0 + HOUR));
});

test('MK-14: a request answered by asking back returns the accepted request; forAccount lists only live ones', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  bg.request(a, b, 'x');
  const r = bg.request(b, a, 'x');
  assert.strictEqual(r.request.status, 'accepted');
  assert.strictEqual(r.request.from_id, a);
  const declined = bg.request(c, a, 'y').request;
  bg.respond(declined.id, a, false);
  assert.deepStrictEqual(bg.forAccount(a).map((x) => x.status), ['accepted']);
  assert.strictEqual(bg.has(a), false);
  assert.ok(!bg.start(a, 'chess', 3).error);
  assert.strictEqual(bg.has(a), true);
});

test('MK-15: pairs are stored in id order whichever way round they are given', () => {
  const [low, high] = [makeUser(), makeUser()];
  chat.connect(high, low);
  assert.ok(chat.connectedSince(low, high) && chat.connectedSince(high, low));
  assert.deepStrictEqual({ ...db.prepare('SELECT user_a, user_b FROM connections WHERE user_a = ? OR user_b = ?').get(low, low) }, { user_a: low, user_b: high });
  chat.disconnect(high, low);
  assert.strictEqual(chat.isConnected(low, high), false);
  friends.request(high, low);
  friends.request(low, high);
  assert.deepStrictEqual({ ...db.prepare('SELECT user_a, user_b FROM friendships WHERE user_a = ?').get(low) }, { user_a: low, user_b: high });
  friends.remove(high, low);
  assert.strictEqual(friends.areFriends(low, high), false);
  friends.remove(makeUser(), makeUser()); // never friends: must not throw
  chat.disconnect(makeUser(), makeUser());
  safety.unblock(makeUser(), makeUser());
  assert.deepStrictEqual(chat.connectionIds(makeUser()), []);
});

test('MK-16: history has "more" only beyond 50; read flags, own-message flag and 120-char previews', () => {
  const [a, b] = [makeUser(), makeUser()];
  const ins = db.prepare('INSERT INTO messages (from_id, to_id, body, created_at, read_at) VALUES (?, ?, ?, ?, ?)');
  for (let i = 0; i < 50; i++) ins.run(b, a, `m${i}`, i, i < 10 ? 1 : null);
  const page = chat.history(a, b);
  assert.strictEqual(page.messages.length, 50);
  assert.strictEqual(page.more, false);
  assert.strictEqual(page.messages[0].read, true);
  assert.strictEqual(page.messages[49].read, false);
  ins.run(a, b, 'y'.repeat(300), 100, null);
  const sum = chat.summaries(a).get(b);
  assert.strictEqual(sum.last.mine, true);
  assert.strictEqual(sum.last.body.length, 120);
  assert.strictEqual(sum.unread, 40);
  assert.strictEqual(chat.summaries(b).get(a).last.mine, false);
});

test('MK-17: CR line endings are normalised too (\\r\\n and lone \\r)', () => {
  const [a, b] = [makeUser(), makeUser()];
  chat.connect(a, b);
  assert.strictEqual(chat.send(a, b, 'x\r\ny\rz').message.body, 'x\ny\nz');
});

// ---- safety: what admins are told ----

test('MK-18: the admin email names the reported person and the reason label; updates and no-admin setups send nothing', () => {
  const reported = makeUser({ first_name: 'Rhea', last_name: 'Stone' });
  const reporter = makeUser();
  const before = outbox.length;
  safety.createReport({ reporterId: reporter, reportedId: reported, reason: 'violence', context: 'match' });
  const mail = outbox.at(-1);
  assert.strictEqual(outbox.length - before, 1);
  assert.strictEqual(mail.subject, 'New report: Rhea Stone');
  assert.match(mail.text, /New report: Violence, threats or self-harm/);
  safety.createReport({ reporterId: reporter, reportedId: reported, reason: 'hate', context: 'match' });
  assert.strictEqual(outbox.length - before, 1, 'an update to an open report is not emailed again');
  const saved = process.env.ADMIN_EMAILS;
  process.env.ADMIN_EMAILS = '';
  try {
    safety.createReport({ reporterId: makeUser(), reportedId: makeUser(), reason: 'spam', context: 'match', activity: 'chess' });
  } finally { process.env.ADMIN_EMAILS = saved; }
  assert.strictEqual(outbox.length - before, 1);
  assert.strictEqual(db.prepare('SELECT activity FROM reports ORDER BY id DESC').get().activity, 'chess');
  safety.createReport({ reporterId: makeUser(), reportedId: makeUser(), reason: 'spam', context: 'match' });
  assert.strictEqual(db.prepare('SELECT activity FROM reports ORDER BY id DESC').get().activity, null);
  assert.deepStrictEqual(Object.values(safety.REASONS).filter((v) => !v), [], 'every reason has a label');
});

// ---- auth: anchors, normalised values, token lifetimes ----

test('MK-19: patterns are anchored at both ends', () => {
  for (const bad of ['x1995-06-15', '1995-06-150']) assert.strictEqual(auth.parseDob(bad), null, bad);
  const err = (email) => auth.validateRegistration({ email }).errors.email;
  assert.ok(err('a@b.cc@d'), 'nothing after the domain');
  assert.ok(!auth.validAvatar('xdata:image/png;base64,AAAA'));
  assert.ok(!auth.validAvatar('data:image/png;base64,AAAA!'));
});

test('MK-20: registration and profile values are normalised (blank -> null, deduplicated, trimmed)', () => {
  const ok = { firstName: 'Ada', lastName: 'Byron', email: 'a@b.co', password: 'abcdefg1', dateOfBirth: '1990-01-01', acceptTerms: true };
  assert.strictEqual(auth.validateRegistration({ ...ok, gender: '' }).value.gender, null);
  assert.strictEqual(auth.validateRegistration({ ...ok, gender: 'man' }).value.gender, 'man');
  assert.strictEqual(auth.validateRegistration(ok).value.avatar, null);
  assert.strictEqual(auth.validateRegistration({ ...ok, password: 'abcdefg1 ' }).value.password, 'abcdefg1 ', 'passwords are not trimmed');
  assert.ok(auth.validateRegistration({ ...ok, lastName: '' }).errors.lastName);
  assert.ok(auth.validateRegistration({ ...ok, avatar: 'data:text/html;base64,AAAA' }).errors.avatar);
  const p = auth.validateProfile({ bio: '   ', country: '', timezone: '', gender: 'robot', languages: ['en', 'en', 'tr'], interests: ['##go', 'Chess'] });
  assert.strictEqual(p.value.bio, null);
  assert.strictEqual(p.value.country, null);
  assert.strictEqual(p.value.timezone, null);
  assert.ok(p.errors.gender);
  assert.deepStrictEqual(JSON.parse(p.value.languages), ['en', 'tr']);
  assert.deepStrictEqual(JSON.parse(p.value.interests), ['#go', 'Chess'], 'only one leading # is removed');
  assert.deepStrictEqual(JSON.parse(auth.validateProfile({ languages: 'en' }).value.languages), []);
  assert.strictEqual(auth.validateProfile({ city: 'Edin\tburgh' }).value.city, 'Edin burgh');
  assert.deepStrictEqual(auth.profileExtras({ interests: '{broken' }).interests, []);
});

test('MK-21: email links expire (verify 24 h, reset 1 h), are single use, and only the newest works', async () => {
  const u = makeUser();
  const v = await atTime(T0, () => auth.createEmailToken(u, 'verify'));
  await atTime(T0 + DAY, () => assert.strictEqual(auth.consumeEmailToken(v, 'verify'), u, 'valid on the last millisecond'));
  const v2 = await atTime(T0, () => auth.createEmailToken(u, 'verify'));
  await atTime(T0 + DAY + 1, () => assert.strictEqual(auth.consumeEmailToken(v2, 'verify'), null));
  const r1 = await atTime(T0, () => auth.createEmailToken(u, 'reset'));
  const r2 = await atTime(T0, () => auth.createEmailToken(u, 'reset'));
  assert.strictEqual(auth.consumeEmailToken(r1, 'reset'), null, 'superseded');
  await atTime(T0 + HOUR + 1, () => assert.strictEqual(auth.consumeEmailToken(r2, 'reset'), null, 'reset links last 1 h'));
  const r3 = await atTime(T0, () => auth.createEmailToken(u, 'reset'));
  assert.strictEqual(auth.consumeEmailToken(r3, 'verify'), null, 'purpose must match');
  await atTime(T0, () => assert.strictEqual(auth.recentlyEmailed(u, 'reset'), true));
  await atTime(T0 + 60e3, () => assert.strictEqual(auth.recentlyEmailed(u, 'reset'), false));
  await atTime(T0 + 59e3, () => assert.strictEqual(auth.recentlyEmailed(u, 'reset'), true));
});

test('MK-22: sessions last 30 days and are looked up by the hash of the cookie', async () => {
  const u = makeUser();
  const token = await atTime(T0, () => auth.createSession(u));
  const cookie = `${auth.COOKIE}=${token}`;
  await atTime(T0 + 30 * DAY, () => assert.strictEqual(auth.sessionFromCookieHeader(cookie).user.id, u));
  await atTime(T0 + 30 * DAY + 1, () => assert.strictEqual(auth.sessionFromCookieHeader(cookie), null));
  assert.strictEqual(auth.sessionFromCookieHeader('other=1'), null);
  assert.strictEqual(db.prepare('SELECT COUNT(*) AS n FROM sessions WHERE token_hash = ?').get(token).n, 0, 'raw token never stored');
  assert.ok(auth.verifyPassword('pw12345678', auth.hashPassword('pw12345678')));
  assert.ok(!auth.verifyPassword('pw12345679', auth.hashPassword('pw12345678')));
  assert.match(auth.hashPassword('x'), /^scrypt\$[A-Za-z0-9+/=]+\$[A-Za-z0-9+/=]+$/);
  assert.deepStrictEqual(auth.parseCookies('a=1=2; b= x '), { a: '1=2', b: 'x' });
});

test('MK-23: admin list parsing trims, lowercases and ignores blanks', () => {
  const saved = process.env.ADMIN_EMAILS;
  process.env.ADMIN_EMAILS = ' Boss@Example.com , ,x@y.z';
  try { assert.deepStrictEqual(auth.adminEmails(), ['boss@example.com', 'x@y.z']); } finally { process.env.ADMIN_EMAILS = saved; }
});

test('MK-24: without TURN, clients get exactly Google\'s two public STUN servers', () => {
  const saved = process.env.TURN_SECRET;
  delete process.env.TURN_SECRET;
  try {
    assert.deepStrictEqual(iceServersFor(1), [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }]);
  } finally { if (saved !== undefined) process.env.TURN_SECRET = saved; }
});

test/unit/matcher.test.js.source:
const test = require('node:test');
const assert = require('node:assert');
const { analyze, score } = require('../../matcher');

const s = (a, b) => score(analyze(a), analyze(b));

test('identical prompts score near 1', () => {
  assert.ok(s('studying calculus', 'Studying calculus!') >= 0.95);
});

test('different phrasings of the same activity match well', () => {
  assert.ok(s('lifting weights at the gym', 'doing a workout') >= 0.5);
  assert.ok(s('programming in python', 'coding a react app') >= 0.5);
  assert.ok(s('running', 'going for a run') >= 0.5);
});

test('tolerates typos', () => {
  assert.ok(s('progamming', 'programming') > 0.4);
});

test('unrelated activities rank below related ones', () => {
  const base = 'studying for my biology exam';
  assert.ok(s(base, 'revising chemistry homework') > s(base, 'playing valorant'));
  assert.ok(s(base, 'playing valorant') < 0.15);
});

test('empty prompts do not match', () => {
  assert.strictEqual(s('', 'coding'), 0);
});

test/unit/matcher.partition.test.js.source:
// Unit tests for matcher.js (requirement FR2 at unit level): systematic functional testing.
//  - stem(): boundary-value analysis of each suffix rule's length threshold (BV-STEM-n).
//  - tokenize()/score(): category partition over the kinds of text people type (TS-MAT-n),
//    see docs/test-specs/matcher-category-partition.md.
// The word-based scorer is what runs when the embedding model is unavailable (EMBEDDINGS=off),
// so it has to be correct on its own.
const test = require('node:test');
const assert = require('node:assert');
const { analyze, score, lexical, semantic, tokenize, stem } = require('../../matcher');

const MIN_SCORE = 0.15; // server.js: the lowest score shown as a match
const s = (a, b) => score(analyze(a), analyze(b));

test('BV-STEM-1: "ies" is stripped only from words longer than 5 letters', () => {
  assert.strictEqual(stem('studies'), 'studi'); // 7 letters
  assert.strictEqual(stem('series'), 'seri'); // 6 letters: just above the boundary
  assert.strictEqual(stem('pies'), 'pi'); // 4 letters: falls through to the "es" rule
});

test('BV-STEM-2: "ing" is stripped only from words longer than 4 letters', () => {
  assert.strictEqual(stem('coding'), 'cod');
  assert.strictEqual(stem('bring'), 'br'); // 5 letters: stripped
  assert.strictEqual(stem('sing'), 'sing'); // 4 letters: kept
  assert.strictEqual(stem('ring'), 'ring');
});

test('BV-STEM-3: "ed" is stripped only from words longer than 4 letters', () => {
  assert.strictEqual(stem('baked'), 'bak');
  assert.strictEqual(stem('bred'), 'bred');
});

test('BV-STEM-4: "es" is stripped only from words longer than 3 letters', () => {
  assert.strictEqual(stem('games'), 'gam');
  assert.strictEqual(stem('toes'), 'to');
  assert.strictEqual(stem('yes'), 'yes');
});

test('BV-STEM-5: a final "s" is stripped from words longer than 3 letters, but not "ss"', () => {
  assert.strictEqual(stem('books'), 'book');
  assert.strictEqual(stem('cats'), 'cat');
  assert.strictEqual(stem('bus'), 'bus');
  assert.strictEqual(stem('class'), 'class');
});

test('BV-STEM-6: a doubled final consonant is undoubled ("running" -> "run"), except l, s, z', () => {
  assert.strictEqual(stem('running'), 'run');
  assert.strictEqual(stem('swimming'), 'swim');
  assert.strictEqual(stem('jazz'), 'jazz');
  assert.strictEqual(stem('spell'), 'spell');
  assert.strictEqual(stem('egg'), 'egg', 'three letters: too short to undouble');
  assert.strictEqual(stem('runs'), 'run');
});

test('TS-MAT-1: tokenize lowercases, drops punctuation, apostrophes and stopwords', () => {
  assert.deepStrictEqual(tokenize("I'm REALLY into Rock'n'Roll!!!"), ['rocknroll']);
  assert.deepStrictEqual(tokenize('  studying   calculus  '), ['studying', 'calculus']);
  assert.deepStrictEqual(tokenize(null), []);
  assert.deepStrictEqual(tokenize(undefined), []);
  assert.deepStrictEqual(tokenize(42), ['42']);
});

test('TS-MAT-2 [single]: text with nothing meaningful never matches anything', () => {
  for (const empty of ['', '   ', 'i am just doing it right now', '!!! ???', '🙂🙂']) {
    assert.strictEqual(s(empty, 'coding a website'), 0, JSON.stringify(empty));
    assert.strictEqual(s(empty, empty), 0, `${JSON.stringify(empty)} with itself`);
  }
});

test('TS-MAT-3: identical wording (any case/punctuation) scores at least 0.95', () => {
  for (const t of ['studying calculus', 'Playing CHESS!', 'reading a book']) {
    assert.ok(s(t, t.toUpperCase() + '.') >= 0.95, t);
  }
});

test('TS-MAT-4: same category, different words, scores at least 0.3 + 0.4 x category overlap', () => {
  // gym / yoga share only the fitness category.
  const a = analyze('gym'), b = analyze('yoga');
  assert.deepStrictEqual([...a.categories], ['fitness']);
  assert.ok(score(a, b) >= 0.7 - 1e-9);
  assert.ok(s('baking bread', 'cooking dinner') >= 0.5);
});

test('TS-MAT-5: different categories with no shared words fall below the match threshold', () => {
  for (const [a, b] of [['playing valorant', 'baking a cake'], ['reading a novel', 'going to the gym'], ['meditating', 'doing my taxes spreadsheet']]) {
    assert.ok(s(a, b) < MIN_SCORE, `${a} / ${b} = ${s(a, b)}`);
  }
});

test('TS-MAT-6: a one-letter typo in a long word still lands in the right category', () => {
  assert.ok(analyze('progamming').categories.has('coding'));
  assert.ok(analyze('studyng').categories.has('studying'));
  assert.ok(s('progamming in javascript', 'programming') >= 0.5);
});

test('TS-MAT-7: very long input is handled and still matches its topic', () => {
  const long = 'coding '.repeat(500) + 'a react website';
  assert.ok(s(long, 'programming') >= 0.5);
});

test('D3 / TS-MAT-8: identical wording in a non-Latin script scores at least 0.95', () => {
  for (const t of ['日本語の勉強', 'читаю книгу', 'أقرأ كتابا', 'ders çalışıyorum', 'μαθαίνω κιθάρα']) {
    assert.ok(s(t, t) >= 0.95, `${t}: ${s(t, t)}`);
  }
});

test('D3 / TS-MAT-9: letters with diacritics are kept, not split into fragments', () => {
  assert.deepStrictEqual(tokenize('satranç oynuyorum'), ['satranç', 'oynuyorum']);
  assert.deepStrictEqual(tokenize('Café crème'), ['café', 'crème']);
  // Leftover fragments ("ık") used to make unrelated Turkish phrases look similar.
  assert.ok(s('ışık tasarımı', 'şık elbise') < MIN_SCORE, `scored ${s('ışık tasarımı', 'şık elbise')}`);
});

test('score is the better of the word score and the meaning score', () => {
  const a = analyze('playing chess'), b = analyze('cooking dinner');
  assert.strictEqual(semantic(a, b), 0, 'no vectors: no meaning score');
  a.vec = Float32Array.from([1, 0]);
  b.vec = Float32Array.from([1, 0]);
  assert.strictEqual(semantic(a, b), 1, 'cosine 1 maps to 1');
  assert.strictEqual(score(a, b), 1);
  b.vec = Float32Array.from([0.25, Math.sqrt(1 - 0.0625)]); // cosine 0.25 = SEMANTIC_LOW
  assert.strictEqual(semantic(a, b), 0);
  b.vec = Float32Array.from([0.5, Math.sqrt(0.75)]); // cosine 0.5: half-way between LOW and HIGH
  assert.ok(Math.abs(semantic(a, b) - 0.5) < 1e-6);
  b.vec = Float32Array.from([0.75, Math.sqrt(1 - 0.5625)]); // cosine 0.75 = SEMANTIC_HIGH
  assert.ok(Math.abs(semantic(a, b) - 1) < 1e-6);
  assert.strictEqual(score(a, b), Math.max(lexical(a, b), semantic(a, b)));
});

test/unit/chat-friends.test.js.source:
// Unit tests for direct messages (chat.js, requirement FR6/SR3) and friendships (friends.js, FR4).
// Category partition of send() inputs, boundary values of length and rate limits (BV-DM-n), and
// the "who may message whom" decision table (DT-DM).
const test = require('node:test');
const assert = require('node:assert');
const { db, makeUser, atTime } = require('../support/db-fixture');
const chat = require('../../chat');
const friends = require('../../friends');
const safety = require('../../safety');

const pair = () => {
  const [a, b] = [makeUser(), makeUser()];
  chat.connect(a, b);
  return [a, b];
};

test('TS-DM-1: text is trimmed, CRLF normalised, and runs of 4+ newlines collapsed to 3', () => {
  const [a, b] = pair();
  const { message } = chat.send(a, b, '  hi\r\nthere\r\n\n\n\n\nbye  ');
  assert.strictEqual(message.body, 'hi\nthere\n\n\nbye');
});

test('TS-DM-2 [error]: empty, whitespace-only and non-string messages are refused', () => {
  const [a, b] = pair();
  for (const body of ['', '   \n  ', null, undefined, 42, { text: 'x' }]) {
    assert.match(chat.send(a, b, body).error, /Type a message/, String(body));
  }
});

test('BV-DM-1: messages may be 2000 characters, not 2001', () => {
  const [a, b] = pair();
  assert.ok(chat.send(a, b, 'x'.repeat(2000)).message);
  assert.match(chat.send(a, b, 'x'.repeat(2001)).error, /up to 2000/);
});

test('DT-DM: only connected or befriended, unblocked, different people can message', () => {
  const [a, b, c, d] = [makeUser(), makeUser(), makeUser(), makeUser()];
  chat.connect(a, b);
  friends.request(a, c);
  friends.request(c, a);
  //            connected friends  blocked  self   -> may message
  const table = [
    [a, b, true],  // connected
    [a, c, true],  // friends
    [a, d, false], // neither
    [a, a, false], // self
  ];
  for (const [x, y, expected] of table) assert.strictEqual(chat.canMessage(x, y), expected, `${x}->${y}`);
  safety.block(b, a);
  assert.strictEqual(chat.canMessage(a, b), false, 'blocked overrides connected');
  assert.match(chat.send(a, b, 'hello').error, /connected with/);
  assert.deepStrictEqual(chat.contacts(a).sort(), [c].sort(), 'blocked contacts are hidden');
});

test('BV-DM-2: at most 15 messages per 10 seconds; the 16th waits for the window to pass', async () => {
  const [a, b] = pair();
  const t0 = Date.UTC(2026, 10, 7, 12);
  await atTime(t0, () => {
    for (let i = 0; i < 15; i++) assert.ok(chat.send(a, b, `m${i}`).message, `message ${i + 1}`);
    assert.match(chat.send(a, b, 'm16').error, /too fast/);
  });
  await atTime(t0 + 10e3, () => assert.ok(chat.send(a, b, 'later').message));
});

test('BV-DM-3: at most 1000 messages per 24 hours', async () => {
  const [a, b] = pair();
  const t0 = Date.UTC(2026, 10, 8, 12);
  const insert = db.prepare('INSERT INTO messages (from_id, to_id, body, created_at) VALUES (?, ?, ?, ?)');
  for (let i = 0; i < 999; i++) insert.run(a, b, 'x', t0 - 60e3);
  await atTime(t0, () => {
    assert.ok(chat.send(a, b, '1000th').message);
    assert.match(chat.send(a, b, '1001st').error, /too fast/);
  });
});

test('history pages 50 at a time, oldest first, with a "more" flag; markRead and summaries agree', () => {
  const [a, b] = pair();
  const insert = db.prepare('INSERT INTO messages (from_id, to_id, body, created_at) VALUES (?, ?, ?, ?)');
  for (let i = 0; i < 51; i++) insert.run(i % 2 ? a : b, i % 2 ? b : a, `m${i}`, 1000 + i);
  const page = chat.history(a, b);
  assert.strictEqual(page.messages.length, 50);
  assert.strictEqual(page.more, true);
  assert.strictEqual(page.messages[0].body, 'm1');
  assert.strictEqual(page.messages.at(-1).body, 'm50');
  const older = chat.history(a, b, page.messages[0].id);
  assert.deepStrictEqual(older.messages.map((m) => m.body), ['m0']);
  assert.strictEqual(older.more, false);
  assert.strictEqual(chat.summaries(a).get(b).unread, 26, 'messages from b (even i) are unread');
  assert.strictEqual(chat.markRead(a, b), 26);
  assert.strictEqual(chat.summaries(a).get(b).unread, 0);
  assert.strictEqual(chat.summaries(a).get(b).last.body, 'm50');
});

test('disconnect removes the connection both ways but keeps messages for moderation', () => {
  const [a, b] = pair();
  chat.send(a, b, 'keep me');
  chat.disconnect(b, a);
  assert.strictEqual(chat.isConnected(a, b), false);
  assert.strictEqual(chat.transcript(a, b).length, 1);
  assert.strictEqual(chat.connectedSince(a, b), null);
});

test('friends: a request becomes a friendship only when both say yes; decline and remove are quiet', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  assert.throws(() => friends.request(a, a), /yourself/);
  assert.strictEqual(friends.request(a, b), 'pending');
  assert.strictEqual(friends.request(a, b), 'pending', 'asking twice is harmless');
  assert.deepStrictEqual(friends.incomingRequestIds(b), [a]);
  assert.strictEqual(friends.areFriends(a, b), false);
  assert.strictEqual(friends.request(b, a), 'friends');
  assert.ok(friends.areFriends(a, b) && friends.areFriends(b, a));
  assert.deepStrictEqual(friends.incomingRequestIds(b), [], 'request consumed');
  assert.strictEqual(friends.request(a, b), 'friends');
  friends.request(c, a);
  friends.decline(c, a);
  assert.deepStrictEqual(friends.incomingRequestIds(a), []);
  friends.remove(b, a);
  assert.strictEqual(friends.areFriends(a, b), false);
  assert.deepStrictEqual(friends.friendIds(a), []);
});

test/unit/background.fsm.test.js.source:
// Model-based testing of the connect-request lifecycle in background.js (requirement FR5).
// The state machine is documented in docs/test-specs/connect-request-fsm.md:
//
//   NONE --request(a,b)--> PENDING(a->b) --respond(b, yes)--> ACCEPTED --settle--> DONE
//                          PENDING(a->b) --request(b,a)----> ACCEPTED   (both asked: mutual yes)
//                          PENDING(a->b) --respond(b, no)--> DECLINED   (hidden; a may ask again)
//                          PENDING(a->b) --cancel(a)-------> NONE       (still counts toward a's daily limit)
//                          PENDING(a->b) --7 days---------->  expired
//                          ACCEPTED      --48 h (no meeting)> expired
//                          any           --forget (block)-->  NONE, history erased
//
// 1. Transition coverage: every transition above (T1..T12) plus the invalid ones (I1..I5) once.
// 2. Random walks (fast-check): long command sequences compared against an executable model.
const test = require('node:test');
const assert = require('node:assert');
const fc = require('fast-check');
const { db, makeUser, atTime } = require('../support/db-fixture');
const bg = require('../../background');

const HOUR = 3600e3;
const DAY = 24 * HOUR;
const statusOf = (a, b) => bg.between(a, b)?.status ?? 'none';

test('T1: request creates a pending request from a to b', () => {
  const [a, b] = [makeUser(), makeUser()];
  const r = bg.request(a, b, 'chess');
  assert.strictEqual(r.status, 'pending');
  assert.strictEqual(r.request.from_id, a);
  assert.strictEqual(r.request.activity, 'chess');
  assert.strictEqual(statusOf(b, a), 'pending', 'visible from either side');
  assert.strictEqual(bg.connected(a, b), false);
});

test('T2: asking again while pending is idempotent', () => {
  const [a, b] = [makeUser(), makeUser()];
  const first = bg.request(a, b, 'chess');
  const again = bg.request(a, b, 'chess');
  assert.strictEqual(again.status, 'pending');
  assert.strictEqual(again.request.id, first.request.id);
  assert.strictEqual(db.prepare('SELECT COUNT(*) AS n FROM connect_requests WHERE from_id = ?').get(a).n, 1);
});

test('T3: b asking a back turns a pending request into a mutual yes', () => {
  const [a, b] = [makeUser(), makeUser()];
  bg.request(a, b, 'chess');
  assert.strictEqual(bg.request(b, a, 'chess').status, 'accepted');
  assert.ok(bg.connected(a, b) && bg.connected(b, a));
});

test('T4/T5: the recipient accepts or declines; a declined request disappears', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  const r1 = bg.request(a, b, 'x').request;
  assert.strictEqual(bg.respond(r1.id, b, true).status, 'accepted');
  assert.strictEqual(statusOf(a, b), 'accepted');
  const r2 = bg.request(a, c, 'x').request;
  assert.strictEqual(bg.respond(r2.id, c, false).status, 'declined');
  assert.strictEqual(statusOf(a, c), 'none');
  assert.deepStrictEqual(bg.forAccount(c), []);
});

test('T6: a may ask again after being declined (a new pending request)', () => {
  const [a, b] = [makeUser(), makeUser()];
  const r = bg.request(a, b, 'x').request;
  bg.respond(r.id, b, false);
  const again = bg.request(a, b, 'x');
  assert.strictEqual(again.status, 'pending');
  assert.notStrictEqual(again.request.id, r.id);
});

test('T7: the sender can cancel a pending request', () => {
  const [a, b] = [makeUser(), makeUser()];
  const r = bg.request(a, b, 'x').request;
  bg.cancel(r.id, a);
  assert.strictEqual(statusOf(a, b), 'none');
});

test('T8: settle turns a pending or accepted request into history (done)', () => {
  const [a, b] = [makeUser(), makeUser()];
  bg.request(a, b, 'x');
  bg.request(b, a, 'x');
  bg.settle(a, b);
  assert.strictEqual(statusOf(a, b), 'none');
  assert.ok(bg.talkedRecently(a, b) && bg.talkedRecently(b, a));
  assert.strictEqual(bg.history(a)[0].status, 'done');
  assert.strictEqual(bg.request(a, b, 'again').status, 'pending', '"call again" starts a new request');
});

test('T9: forget (block) erases everything between two people, including history', () => {
  const [a, b] = [makeUser(), makeUser()];
  bg.request(a, b, 'x');
  bg.settle(a, b);
  bg.request(b, a, 'y');
  bg.forget(a, b);
  assert.strictEqual(statusOf(a, b), 'none');
  assert.strictEqual(bg.talkedRecently(a, b), false);
  assert.deepStrictEqual(bg.history(a), []);
});

test('T10 (boundary): a pending request expires exactly 7 days after it was sent', async () => {
  const [a, b] = [makeUser(), makeUser()];
  const t0 = Date.UTC(2026, 10, 3, 9);
  await atTime(t0, () => bg.request(a, b, 'x'));
  await atTime(t0 + 7 * DAY - 1, () => assert.strictEqual(statusOf(a, b), 'pending'));
  await atTime(t0 + 7 * DAY, () => {
    assert.strictEqual(statusOf(a, b), 'none');
    const r = db.prepare('SELECT id FROM connect_requests WHERE from_id = ?').get(a);
    assert.strictEqual(bg.respond(r.id, b, true), null, 'an expired request cannot be accepted');
  });
});

test('T11 (boundary): an accepted connection without a meeting lapses after 48 hours', async () => {
  const [a, b] = [makeUser(), makeUser()];
  const t0 = Date.UTC(2026, 10, 3, 9);
  await atTime(t0, () => { bg.request(a, b, 'x'); bg.request(b, a, 'x'); });
  await atTime(t0 + 48 * HOUR - 1, () => assert.strictEqual(bg.connected(a, b), true));
  await atTime(t0 + 48 * HOUR, () => assert.strictEqual(bg.connected(a, b), false));
});

test('T12 (boundary): a scheduled meeting keeps the connection open until 2 hours after it starts', async () => {
  const [a, b] = [makeUser(), makeUser()];
  const t0 = Date.UTC(2026, 10, 3, 9);
  const meeting = t0 + 5 * DAY;
  await atTime(t0, () => {
    const id = bg.request(a, b, 'x').request.id;
    bg.respond(id, b, true);
    assert.ok(!bg.propose(id, a, [meeting]).error);
    assert.strictEqual(bg.pick(id, b, meeting).meeting_at, meeting);
  });
  await atTime(meeting + 2 * HOUR - 1, () => assert.strictEqual(bg.connected(a, b), true));
  await atTime(meeting + 2 * HOUR, () => assert.strictEqual(bg.connected(a, b), false));
});

test('I1-I5: invalid transitions are refused and change nothing', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  assert.match(bg.request(a, a, 'x').error, /That’s you/); // I1 self
  const r = bg.request(a, b, 'x').request;
  assert.strictEqual(bg.respond(r.id, a, true), null); // I2 sender answers own request
  assert.strictEqual(bg.respond(r.id, c, true), null); // I3 a third person answers
  bg.cancel(r.id, b); // I4 recipient "cancels" (only the sender can)
  assert.strictEqual(statusOf(a, b), 'pending');
  bg.respond(r.id, b, true);
  bg.cancel(r.id, a); // I5 cancel after acceptance
  assert.strictEqual(statusOf(a, b), 'accepted');
  assert.strictEqual(bg.respond(r.id, b, false), null, 'cannot decline once accepted');
});

test('D5 (boundary): at most 20 new requests a day, and cancelling does not reset the count', () => {
  const a = makeUser();
  for (let i = 0; i < 20; i++) {
    const r = bg.request(a, makeUser(), 'x');
    assert.strictEqual(r.status, 'pending', `request ${i + 1}`);
    bg.cancel(r.request.id, a); // withdraw it straight away
  }
  assert.match(bg.request(a, makeUser(), 'x').error || '', /a lot of requests/, '21st request in a day is refused');
});

// ---- Scheduling (part of the ACCEPTED state) ----

test('BV-SLOT: proposed times must be more than 5 minutes and less than 30 days ahead, at most 3', async () => {
  const [a, b] = [makeUser(), makeUser()];
  const now = Date.UTC(2026, 10, 4, 12);
  await atTime(now, () => {
    const id = bg.request(a, b, 'x').request.id;
    bg.respond(id, b, true);
    const MIN = 5 * 60e3, MAX = 30 * DAY;
    assert.match(bg.propose(id, a, [now + MIN]).error, /at least one time/, 'exactly 5 min ahead is too soon');
    assert.deepStrictEqual(JSON.parse(bg.propose(id, a, [now + MIN + 1]).proposed_slots), [now + MIN + 1]);
    assert.match(bg.propose(id, a, [now + MAX]).error, /at least one time/, 'exactly 30 days ahead is too far');
    assert.ok(!bg.propose(id, a, [now + MAX - 1]).error);
    const four = [1, 2, 3, 4].map((h) => now + h * HOUR);
    assert.match(bg.propose(id, a, four).error, /up to 3/);
    const dupes = [now + HOUR, now + HOUR, String(now + 2 * HOUR), 'junk', null];
    assert.deepStrictEqual(JSON.parse(bg.propose(id, a, dupes).proposed_slots), [now + HOUR, now + 2 * HOUR], 'deduped, sorted, junk dropped');
    assert.match(bg.propose(id, a, 'not a list').error, /at least one time/);
  });
});

test('scheduling: only the other person can pick, only a proposed and future time, and unschedule resets', async () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  const now = Date.UTC(2026, 10, 5, 12);
  const slot = now + 3 * HOUR;
  let id;
  await atTime(now, () => {
    id = bg.request(a, b, 'x').request.id;
    assert.match(bg.propose(id, a, [slot]).error, /no longer open/, 'not accepted yet');
    bg.respond(id, b, true);
    bg.propose(id, a, [slot, slot + HOUR]);
    assert.match(bg.pick(id, a, slot).error, /no longer open/, 'proposer cannot pick');
    assert.match(bg.pick(id, c, slot).error, /no longer open/, 'outsider cannot pick');
    assert.match(bg.pick(id, b, slot + 1).error, /one of the proposed/);
  });
  await atTime(slot + 1, () => assert.match(bg.pick(id, b, slot).error, /has passed/));
  await atTime(now, () => {
    assert.strictEqual(bg.pick(id, b, String(slot + HOUR)).meeting_at, slot + HOUR);
    assert.ok(bg.unschedule(id, a));
    const row = db.prepare('SELECT * FROM connect_requests WHERE id = ?').get(id);
    assert.strictEqual(row.meeting_at, null);
    assert.strictEqual(row.proposed_slots, null);
    assert.strictEqual(bg.unschedule(id, c), null);
  });
});

test('reminders fire once, within 10 minutes before a meeting', async () => {
  const [a, b] = [makeUser(), makeUser()];
  const now = Date.UTC(2026, 10, 6, 12);
  const meeting = now + HOUR;
  await atTime(now, () => {
    const id = bg.request(a, b, 'x').request.id;
    bg.respond(id, b, true);
    bg.propose(id, a, [meeting]);
    bg.pick(id, b, meeting);
  });
  const mine = (rows) => rows.filter((r) => r.from_id === a);
  await atTime(meeting - 10 * 60e3 - 1, () => assert.strictEqual(mine(bg.dueReminders()).length, 0));
  await atTime(meeting - 10 * 60e3, () => assert.strictEqual(mine(bg.dueReminders()).length, 1));
  await atTime(meeting - 5 * 60e3, () => assert.strictEqual(mine(bg.dueReminders()).length, 0, 'only once'));
});

// ---- Random walks against an executable model ----

function model() {
  const live = new Map(); // "x|y" (sorted) -> { from, to, status }
  const sent = new Map(); // user -> requests created today
  const key = (x, y) => (x < y ? `${x}|${y}` : `${y}|${x}`);
  return {
    live, key,
    request(x, y) {
      if (x === y) return 'error';
      const l = live.get(key(x, y));
      if (l) {
        if (l.status === 'pending' && l.to === x) l.status = 'accepted';
        return l.status;
      }
      if ((sent.get(x) || 0) >= 20) return 'error';
      sent.set(x, (sent.get(x) || 0) + 1);
      live.set(key(x, y), { from: x, to: y, status: 'pending' });
      return 'pending';
    },
    respond(x, y, accept) {
      const l = live.get(key(x, y));
      if (!l || l.status !== 'pending' || l.to !== x) return null;
      if (accept) l.status = 'accepted';
      else live.delete(key(x, y));
      return accept ? 'accepted' : 'declined';
    },
    cancel(x, y) {
      const l = live.get(key(x, y));
      if (l && l.status === 'pending' && l.from === x) live.delete(key(x, y));
    },
    settle(x, y) { live.delete(key(x, y)); },
  };
}

test('random command sequences behave like the model (fast-check, 200 walks)', () => {
  const cmd = fc.tuple(fc.constantFrom('request', 'respond', 'cancel', 'settle'), fc.nat(3), fc.nat(3), fc.boolean());
  fc.assert(
    fc.property(fc.array(cmd, { minLength: 1, maxLength: 40 }), (cmds) => {
      const users = [makeUser(), makeUser(), makeUser(), makeUser()];
      const m = model();
      for (const [op, i, j, flag] of cmds) {
        const [x, y] = [users[i], users[j]];
        if (op === 'request') {
          const r = bg.request(x, y, 'walk');
          assert.strictEqual(r.error ? 'error' : r.status, m.request(x, y), `request ${i}->${j}`);
        } else if (op === 'respond') {
          const id = bg.between(x, y)?.id ?? 0;
          assert.strictEqual(bg.respond(id, x, flag)?.status ?? null, m.respond(x, y, flag), `respond ${i}<-${j}`);
        } else if (op === 'cancel') {
          bg.cancel(bg.between(x, y)?.id ?? 0, x);
          m.cancel(x, y);
        } else if (x !== y) {
          bg.settle(x, y);
          m.settle(x, y);
        }
        // Invariant: the implementation's view of every pair equals the model's.
        for (const p of users) for (const q of users) {
          if (p >= q) continue;
          const l = m.live.get(m.key(p, q));
          const r = bg.between(p, q);
          assert.strictEqual(r?.status ?? 'none', l?.status ?? 'none', `pair ${p},${q} after ${op}`);
          if (l) assert.strictEqual(r.from_id, l.from);
          assert.strictEqual(bg.connected(p, q), l?.status === 'accepted');
        }
      }
    }),
    { numRuns: 200 },
  );
});

// ---- Background searches (added after mutation run 1 showed start/stop/limits were only integration-tested) ----

test('background searches: at most 3 per person, same wording extends, an id edits, stop one or all, expiry', async () => {
  const a = makeUser();
  const t0 = Date.UTC(2026, 10, 9, 8);
  await atTime(t0, () => {
    const s1 = bg.start(a, 'chess', 3);
    assert.strictEqual(s1.expiresAt, t0 + 3 * HOUR);
    assert.strictEqual(bg.start(a, 'Chess', 24).id, s1.id, 'same wording (any case) extends instead of adding');
    assert.strictEqual(bg.forUser(a).length, 1);
    assert.strictEqual(bg.forUser(a)[0].expiresAt, t0 + 24 * HOUR);
    bg.start(a, 'go', 3);
    bg.start(a, 'poker', 3);
    assert.match(bg.start(a, 'bridge', 3).error, /up to 3/);
    const edited = bg.start(a, 'speed chess', 12, s1.id);
    assert.strictEqual(edited.id, s1.id);
    assert.strictEqual(edited.activity, 'speed chess');
    assert.match(bg.start(a, 'x', 3, 999999).error, /has ended/);
    assert.match(bg.start(makeUser(), 'x', 3, s1.id).error, /has ended/, "someone else's search id");
    bg.stop(a, s1.id);
    assert.deepStrictEqual(bg.forUser(a).map((s) => s.activity).sort(), ['go', 'poker']);
  });
  await atTime(t0 + 3 * HOUR, () => {
    assert.deepStrictEqual(bg.forUser(a), [], 'expired exactly at expiresAt');
    assert.strictEqual(bg.has(a), false);
  });
  await atTime(t0, () => { bg.stop(a); assert.deepStrictEqual(bg.forUser(a), []); });
});

test('reopen: an accepted request is reused, a pending one accepted, otherwise a new accepted one is made', () => {
  const [a, b, c] = [makeUser(), makeUser(), makeUser()];
  const fresh = bg.reopen(a, b, 'planning');
  assert.strictEqual(fresh.status, 'accepted');
  assert.strictEqual(fresh.activity, 'planning');
  assert.strictEqual(bg.reopen(b, a, 'x').id, fresh.id);
  const pending = bg.request(c, a, 'y').request;
  const r = bg.reopen(a, c, 'z');
  assert.strictEqual(r.id, pending.id);
  assert.strictEqual(bg.between(a, c).status, 'accepted');
});

